import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface CodeRedIn {
  /** Known patient; omit for an unidentified trauma patient */
  patient_id?: number | null;
  /** e.g. 'Unknown Male 1' (generated if omitted) */
  temp_identifier?: string | null;
  gender?: "male" | "female" | "other" | "unknown";
  approx_age_years?: number | null;
  /** Destination ward; or ward_type (GET /beds/matrix?include_beds=false) */
  ward_id?: number | null;
  ward_type?: "ICU" | "CCU" | "Emergency" | "Surgical" | "General" | null;
  needs_ot?: boolean;
  /** With needs_ot: the theatre to hold (GET /ot/theaters) */
  ot_id?: number | null;
  procedure_name?: string | null;
  eta_minutes?: number | null;
  /** What the receiving team should know now; the doctor records the reason and diagnosis later (admission-details) */
  notes?: string | null;
  /** The patient's ER visit (default: the open one, or a new one): a Code Red is recorded there as triage level 1 */
  er_visit_id?: number | null;
  /** The medico-legal checklist if already known (else later: POST /er/visits/{er_visit_id}/medico-legal) */
  is_medico_legal?: boolean | null;
  /** Required when medico-legal (GET /mlc/case-types) */
  mlc_case_type_id?: number | null;
}

